        else:
            for p in c['p_torso']: sandbox.set_pad_active(p, True)
        sandbox.set_motor(c['joint'], -speed, torque)

def agent_action(sandbox, agent_body, step_count):
    _apply_climb_action(sandbox, agent_body, step_count)

import math

def build_agent(sandbox):
    # Main beam with sufficient mass and dimensions
    chassis = sandbox.add_beam(x=4.5, y=1.5, width=2.0, height=3.0, density=5.0)

    # Pads placed within build zone and within wall contact range
    pad1 = sandbox.add_pad(x=3.5, y=1.5, radius=0.25, density=5.0)
    pad2 = sandbox.add_pad(x=5.0, y=1.5, radius=0.25, density=5.0)

    # Pivot joints connecting chassis to pads
    joint1 = sandbox.add_joint(chassis, pad1, (3.5, 1.5), type='pivot')
    joint2 = sandbox.add_joint(chassis, pad2, (5.0, 1.5), type='pivot')

    # Additional beam for structural support and weight distribution
    third_beam = sandbox.add_beam(x=4.5, y=4.5, width=1.0, height=2.0, density=5.0)
    joint3 = sandbox.add_joint(chassis, third_beam, (4.5, 4.5), type='pivot')

    # Return structure with control parameters
    return {
        'chassis': chassis,
        'p_torso': [pad1, pad2],
        'joints': [joint1, joint2, joint3],
        'control': {
            'cycle': 10,
            'overlap': 10,
            'speed': 5.0,
            'torque': 100.0,
            'p_torso': [pad1, pad2],
            'p_arm': [],
            'joint': joint3
        }
    }

def _apply_climb_action(sandbox, agent_body, step_count):
    c = agent_body.get("control", {}) if isinstance(agent_body, dict) else {}
    if not c:
        return
    cycle = c['cycle']
    phase = step_count % (2 * cycle)
    overlap = c.get('overlap', 10)
    speed = c.get('speed', 5.0)
    torque = c.get('torque', 100.0)

    if phase < cycle:
        # Activate torso pads for wall adhesion
        for p in c['p_torso']:
            sandbox.set_pad_active(p, True)
        # Deactivate arm pads after overlap
        if phase > overlap:
            for p in c['p_arm']:
                sandbox.set_pad_active(p, False)
        else:
            for p in c['p_arm']:
                sandbox.set_pad_active(p, True)
        # Apply motor torque to main joint
        sandbox.set_motor(c['joint'], speed, torque)
    else:
        # Activate arm pads
        for p in c['p_arm']:
            sandbox.set_pad_active(p, True)
        # Deactivate torso pads after overlap
        if (phase - cycle) > overlap:
            for p in c['p_torso']:
                sandbox.set_pad_active(p, False)
        else:
            for p in c['p_torso']:
                sandbox.set_pad_active(p, True)
        # Apply reverse torque
        sandbox.set_motor(c['joint'], -speed, torque)

def agent_action(sandbox, agent_body, step_count):
    _apply_climb_action(sandbox, agent_body, step_count)
